contract InvMutTest {
    C c;
    bool failTransferFrom;
    constructor(C _c) { c = _c; }
    function run(address[] memory tos, uint v, bool shouldFail) public {
        require(tos.length > 0);
        failTransferFrom = shouldFail;
        bool reverted;
