contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, address from, address to, uint v) public payable {
        require(address(this).balance >= amount);
        uint balThisBefore = address(this).balance;
        uint balCBefore = address(c).balance;
        bool ok = c.transfer{value: amount}(from, address(this), this.singleTo(to), v);
        uint balThisAfter = address(this).balance;
        uint balCAfter = address(c).balance;
        assert(ok && balThisAfter == balThisBefore && balCAfter == balCBefore);
    }
    function singleTo(address a) external pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }
    fallback() external payable {}
    receive() external payable {}
}

